import type { APIRoute } from 'astro'
import satori from 'satori'
import { Resvg } from '@resvg/resvg-js'
import { readFileSync } from 'fs'
import { PROMPT_CATEGORIES } from '../data/prompts-data'
import { faqByLang } from '../data/faq-data'
import { t } from '../data/i18n'
import { resolve } from 'path'

export const GET: APIRoute = async () => {
  // Counters come from the same sources as the pages: guide files generated by
  // prepare-guide-content.mjs, the prompt categories, the golden rules and the FAQ.
  const workflowCount = Object.keys(import.meta.glob('../content/docs/guide/workflows/*.md'))
    .filter(file => !file.endsWith('/index.md')).length
  const stats = [
    { value: String(workflowCount), label: 'WORKFLOWS' },
    { value: String(PROMPT_CATEGORIES.reduce((sum, category) => sum + category.count, 0)), label: 'PROMPTS' },
    { value: String(t('en').rules.length), label: 'GOLDEN RULES' },
    { value: String(faqByLang.en.reduce((sum, section) => sum + section.items.length, 0)), label: 'FAQ' },
  ]

  // Brand fonts as TTF: satori does not read the WOFF2 subsets served by the site.
  // Paths start at the project root: once bundled, this module runs from dist/pages/.
  const font = (file: string) =>
    readFileSync(resolve(process.cwd(), 'src/assets/og-fonts', file)).buffer as ArrayBuffer
  const hatching = readFileSync(resolve(process.cwd(), 'public/images/brand/section-hatching.svg'))

  // Dark band tokens from src/styles/global.css ([data-theme="dark"]) and the action orange.
  const C = {
    band: '#141414',
    card: '#202020',
    border: '#444444',
    text: '#f3f0e9',
    textSecondary: '#dedbd5',
    textMuted: '#c4c1bb',
    accent: '#ffb17a',
    action: '#f97316',
  }
  const display = { fontFamily: 'Barlow Condensed', fontWeight: 700, letterSpacing: '-0.015em' }
  const mono = { fontFamily: 'IBM Plex Mono', fontWeight: 400 }

  const svg = await satori(
    ({
      type: 'div',
      props: {
        style: {
          width: '1200px',
          height: '630px',
          background: C.band,
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          fontFamily: 'IBM Plex Sans',
          position: 'relative',
          padding: '56px 72px 96px',
        },
        children: [
          // Parquet hatching of .section-wallpaper, at the portfolio pattern opacity
          {
            type: 'div',
            props: {
              style: {
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                backgroundImage: `url(data:image/svg+xml;base64,${hatching.toString('base64')})`,
                backgroundSize: '160px 160px',
                backgroundRepeat: 'repeat',
                opacity: 0.09,
              },
            },
          },
          // Orange rule on top of the band, as .page-hero
          {
            type: 'div',
            props: { style: { position: 'absolute', top: 0, left: 0, right: 0, height: '8px', background: C.action } },
          },
          // Kicker: mono, uppercase, accent, 28px dash
          {
            type: 'div',
            props: {
              style: { display: 'flex', alignItems: 'center', gap: '14px', marginBottom: '20px' },
              children: [
                { type: 'div', props: { style: { width: '28px', height: '2px', background: C.accent } } },
                {
                  type: 'span',
                  props: {
                    style: { ...mono, fontSize: '18px', letterSpacing: '0.12em', color: C.accent },
                    children: 'FREE & OPEN SOURCE',
                  },
                },
              ],
            },
          },
          // Title
          {
            type: 'div',
            props: {
              style: { display: 'flex', gap: '22px', marginBottom: '12px' },
              children: [
                {
                  type: 'span',
                  props: {
                    style: { ...display, fontSize: '112px', color: C.text, lineHeight: 1 },
                    children: 'Claude Cowork',
                  },
                },
                {
                  type: 'span',
                  props: {
                    style: { ...display, fontSize: '112px', color: C.action, lineHeight: 1 },
                    children: 'Guide',
                  },
                },
              ],
            },
          },
          // Subtitle
          {
            type: 'div',
            props: {
              style: { fontSize: '28px', color: C.textSecondary, marginBottom: '44px' },
              children: 'Practical guide to Claude Cowork for small businesses',
            },
          },
          // Stats row: brand cards with the hard offset shadow
          {
            type: 'div',
            props: {
              style: { display: 'flex', gap: '20px' },
              children: stats.map(({ value, label }) => ({
                type: 'div',
                props: {
                  style: {
                    background: C.card,
                    border: `1px solid ${C.border}`,
                    borderRadius: '8px',
                    boxShadow: `4px 4px 0 ${C.border}`,
                    padding: '16px 24px',
                    display: 'flex',
                    flexDirection: 'column',
                    flexGrow: 1,
                    flexBasis: 0,
                  },
                  children: [
                    {
                      type: 'span',
                      props: {
                        style: { ...display, fontSize: '56px', color: C.action, lineHeight: 1 },
                        children: value,
                      },
                    },
                    {
                      type: 'span',
                      props: {
                        style: { ...mono, fontSize: '15px', color: C.textMuted, letterSpacing: '0.1em', marginTop: '8px' },
                        children: label,
                      },
                    },
                  ],
                },
              })),
            },
          },
          // FB. signature
          {
            type: 'div',
            props: {
              style: {
                position: 'absolute',
                bottom: '36px',
                left: '72px',
                display: 'flex',
                alignItems: 'center',
                gap: '14px',
              },
              children: [
                { type: 'span', props: { style: { ...display, fontSize: '34px', color: C.action }, children: 'FB.' } },
                { type: 'span', props: { style: { ...mono, fontSize: '17px', color: C.textMuted }, children: 'florian.bruniaux.com' } },
              ],
            },
          },
        ],
      },
    } as any),
    {
      width: 1200,
      height: 630,
      fonts: [
        { name: 'Barlow Condensed', data: font('barlow-condensed-700.ttf'), weight: 700, style: 'normal' },
        { name: 'IBM Plex Sans', data: font('ibm-plex-sans-400.ttf'), weight: 400, style: 'normal' },
        { name: 'IBM Plex Mono', data: font('ibm-plex-mono-400.ttf'), weight: 400, style: 'normal' },
      ],
    }
  )

  const resvg = new Resvg(svg, { fitTo: { mode: 'width', value: 1200 } })
  const png = resvg.render().asPng()

  return new Response(png.buffer as ArrayBuffer, {
    headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=86400' },
  })
}
